from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parents[1]
DATE='November 21, 2026'

USER=[
('Getting started',[
('Purpose and installation','Carillon Bells 9.0 is the separate C# WPF edition of Westminster Chimes and Carillon Bells. It stores playlists and settings in SQLite beside the executable. Keep the working Delphi 8.1 installation in its existing folder. Extract the entire 9.0 package into a different writable folder. Do not extract over 8.1 or point both applications at one database.'),
('Starting the application','Run CarillonBells.exe. The self-contained package includes the .NET runtime. The first start asks to create a blank database if databases\\carillon.db is absent. Choose Yes to start a fresh installation, then use Database import to import a copy of an existing database. The imported source is opened read-only; it is not converted in place.'),
('Evaluation mode','Launch with --evaluation during development or evaluation. This suppresses automatic SMTP alerts and morning reports. Manual email tests still require an explicit confirmation. Evaluation mode can play scheduled audio and control the Windows master volume. Keep the application away from a live bell amplifier until schedules and output levels have been reviewed.'),
('Portable files','The executable directory is the base for databases, logs, help, artwork and data\\keepalive.txt. The current working directory does not determine data locations. Keep the whole extracted folder together. All playback paths resolve within the running executable folder. Legacy drive-letter paths use the same folder layout under this folder. Copy the complete installation, including its database and music, when moving to another drive or device. Network paths and paths outside the installation are rejected.'),
('First checks','Check the organization name, playlist count, system date, Windows output device and volume. Review the next bell and today\'s schedule. Inspect every directory override and silence rule. The application does not copy your music collection. A database imported into a different folder may refer to music that is not present there.')]),
('Editing the playlist',[
('Choose and find songs','The music list groups records by season. Expand and Collapse control the groups. Search matches song titles or groups. Select a row to load its own schedule. Double-click a song row, or select it and click Play, to test playback. The group heading displays song count and combined duration. First, Previous, Next and Last navigate visible records.'),
('Set the schedule','Choose From and Until dates, inclusive. Select Monday through Sunday as needed. Enter up to twelve distinct daily times. HH:mm:ss and h:mm AM/PM are accepted. An empty time is absent; 00:00:00 is a real midnight event. Enter a repeat count from 1 through 5. The group name can be edited in the detail panel.'),
('Save and Cancel','Focusing a schedule editor begins an edit session and pauses an enabled schedule. Save validates and writes the selected composite key. Cancel discards pending edits. The previous enabled state is restored at the end of the edit session. Navigation or closing with pending edits offers Save, Discard or Cancel. Save and Cancel preserve group expansion and the selected record using its stable key.'),
('Add and remove music','Add files accepts one or more MP3 or WAV files. Duration is read through the independent audio path. Copy audio into the portable application folder before adding it. Selected files are stored with relative paths so they follow the installation when copied. Duplicate playlist-name and song-path pairs are rejected by SQLite. Delete confirms removal of the playlist record and keeps the audio file. Changes reload automatically; deleting the selected song selects a neighboring record. The previous schedule state is restored.'),
('Seasonal synchronization','When scheduling resumes, recognized group settings are copied into matching seasonal playlist records, excluding Daily List. The group From and Until dates and first play time replace individual seasonal values, and times 2 through 12 are cleared. This preserves the existing application behavior. Make recurring seasonal timing changes through Music groups.')]),
('Scheduling playback and silence',[
('Enable and view scheduling','Schedule enabled controls dispatch. Today\'s schedule displays the full-day schedule and the remaining queue. Report calculations use an independent full-day snapshot, so pausing the live queue does not erase report totals. Different songs at the same time remain separate and play in deterministic order. Playback is serialized.'),
('Time changes and restarts','After a detected sleep or wall-clock discontinuity, missed events are skipped. The queue is rebuilt for current and future times. A persistent occurrence ledger prevents an already dispatched scheduled occurrence from playing again after re-enable or restart on that date. Normal contention while a song is already playing retains sequential queue behavior.'),
('Manual player and Windows volume','Play loads the selected real file. Pause toggles pause and resume; Stop releases playback. The player shows the title and remaining duration. MP3 decoding uses NLayer, while PCM WAV reading and Windows waveOut provide the other path. The volume slider and Mute button control the default Windows endpoint, and tray changes update the controls. The slider is disabled while muted.'),
('Weekly silence','Silence windows contains twelve reusable rules with Enabled, Purpose, Start, End and seven weekday flags. Overnight rules belong to the starting weekday. Equal start and end is inactive. Overlapping reasons are combined. Existing schedule compilation suppresses the exact end instant inclusively, while live muting uses an exclusive end. Disabled rules remain available for later reuse.'),
('Liturgical and funeral silence','System contains the separate legacy silence settings. Ash Wednesday and All Souls run from 02:05 to 23:55. Holy Thursday through Holy Saturday spans the corresponding begin and end. Funeral silence uses complete begin and end dates and times. Clear funeral dates removes that one-off interval. The silence coordinator preserves a prior manual mute and does not unmute while another reason remains active.')]),
('Administration and themes',[
('Administration behavior','Opening Groups, System, Email, Random music, Silence windows or Database import pauses scheduling. Closing administration reloads the playlist automatically and restores the previous schedule state. An already paused schedule remains paused. The selected song, search and group expansion are preserved where possible. Clock and Log do not suspend background work. Themes opened alone does not pause scheduling.'),
('Music groups','Edit group names, dates and play times in the grid. Add group creates a pending row; Delete group removes the selected row after confirmation. Save commits changes and Cancel changes reloads committed records. Recalculate dates for upcoming year updates known holiday groups while preserving custom groups. Christmas remains December 22 through December 26.'),
('Random music','Slot 1 is the default directory. Slots 2 through 7 are annual date-window overrides, evaluated in slot order. The first matching nonempty override wins. Cross-year ranges such as December to January are supported. Select a row and Browse for selected directory to choose a folder inside this portable installation. The selected directory is stored as a relative path. Save explicitly. Placeholder titles containing Random Music Generator select an MP3 from the active directory at playback time.'),
('System and appearance','System owns organization, logging and legacy silence fields. Displayed and entered dates use U.S. MM/dd/yyyy with slashes; optional values can be blank. Recalculate Easter and All Souls proposes new dates; Save keeps them. Themes offers the eleven legacy palettes, the approved blue and parchment designs, and persisted custom background and text colors. Changes apply to open windows immediately.'),
('Saving settings','Administration changes remain pending across tabs until Save. Save validates edited tables and writes only settings fields that changed. This avoids one settings page overwriting unrelated values saved by another. Cancel changes reloads all pending administration edits. Closing with changes offers Save, Discard or Cancel. Theme changes are saved immediately and separately.')]),
('Reports logs clock and help',[
('Email configuration','Enter the enabled flag, SMTP host, explicit STARTTLS port, username, password or app password, From address and recipient lists. Show password changes visibility only. Save explicitly. Send test message and Test morning report ask before sending to configured recipients. A failed DNS, network, authentication or TLS operation reports failure rather than success.'),
('Morning report','The automatic report is due at or after 05:00 once per running day. Starting after 05:00 suppresses a catch-up send for that date. Evaluation mode suppresses all automatic mail. Preview report saves a local HTML report containing organization, drive usage, boot and application uptime, CPU/RAM information, actual audio backend, schedules, play activity, yesterday\'s recorded count, maintenance, missing files and health score.'),
('Logs and played counts','Log opens a newest-first viewer limited to the latest 1,000 entries. Refresh reads updated data. Today\'s recorded play count is reconstructed from Played Song entries after restart. Old checkpoint messages are ignored. Plays while logging is disabled cannot be reconstructed. Log trimming runs at startup and daily after 00:10, independently of whether playback logging is enabled. Malformed historical timestamps are preserved.'),
('Clock','Clock opens the familiar artwork with live hour and minute hands. It scales proportionally and can be restored or maximized. File then Close returns to the main window. Scheduled playback and maintenance continue while the clock is displayed. The original clock has no second hand; the display refreshes every second.'),
('Help and exit','Help opens the local HTML manual. Basic help remains available without a network connection; the GTranslate floating widget needs internet access for translation. Product names are protected from translation. Exit, File then Exit, and the window close button use the same cleanup path. Pending edits are checked before closing.')]),
('Maintenance and troubleshooting',[
('Background maintenance','The application prevents automatic system sleep while active and releases that hold at exit. It writes data\\keepalive.txt every thirty seconds. Schedule and count maintenance runs after 00:05, log trimming after 00:10, annual liturgical maintenance after January 2 at 00:15, and group maintenance after January 3 at 00:02. These jobs do not depend on a settings page being visible.'),
('Database import and recovery','Analyze source database checks integrity and directory schema read-only. Import works on a copy inside the separate application and preserves unknown tables and legacy backups. Before replacement or upgrade it creates a ZIP snapshot. Older wide directories migrate transactionally into seven slots; legacy times normalize on the copy. Save report exports conversion results. Keep private databases and ZIPs out of public repositories and release packages.'),
('No sound or missing songs','Check Windows default output, tray mute, active silence reasons and volume. Database import does not copy audio files. Copy the music folders beside the new executable with their stored relative layout, including Music and Songs where referenced. A missing-file message shows the expected full path. Legacy drive-letter paths resolve to the corresponding folder layout beside the running executable; copy that audio into this installation. The application accepts MP3 and PCM or IEEE-float WAV.'),
('Startup and storage errors','A second instance in the same portable folder is refused by an exclusive lock. A writable portable folder is required for SQLite, logs and keepalive data. Disconnected or read-only storage needs correction before operation can continue. Do not run an installation directly from a ZIP archive. Reconnect a USB drive and verify its files before retrying.'),
('Before deployment','Evaluate the separate 9.0 executable using copied data. Check x86 or x64 architecture, audio devices, monitor scaling and actual music. Exercise silence transitions and authorized email tests. Keep 8.1 live until user acceptance of the full replacement. The source repository is experimental; publishing source does not approve a production replacement release.')])]

ENGINEER=[
('Scope and source baselines',[
('Migration boundary','This project implements the separate Carillon Bells 9.0 Windows desktop edition in C# and WPF. The protected Delphi reference is Carillon8_1- Portable - FMX at commit 77c6252985d0ed7db68227bf80478fd692ef0a1c. The approved WPF design reference is commit 941654ed71543d56719fe6fd5e0ac55eeebf9adb. Neither reference is an implementation destination. The existing 8.1 GitHub repository and releases remain live.'),
('Evidence','source-inventory.json records source/form/project files, hashes, routines, form controls and event wiring. database-schema.json records the supplied private baseline schema, constraints, indexes and storage-type counts without configuration values. FMX2CSharp-handoff.md preserves the handoff. Validation results and the acceptance matrix distinguish implemented behavior from environmental or user acceptance checks.'),
('Private data boundary','The supplied reference copy has SHA-256 4F7C94216CC4F403C6AAC310AE4645851597EABC056798C6A87796C0444C09BE. It is not a redistributable sample. Development uses another copy under ignored output folders. Databases, journals, logs, credentials, dumps, compiler outputs and package staging are ignored. Release packages start without the private database and do not include Songs or old_Songs.'),
('License','New project code is Apache License 2.0 by user decision. NOTICE preserves the MIT license and Tommy Martin attribution from the reused Delphi/prototype material. Dependency notices must accompany distributions. The independent MP3 decoder and NAudio are MIT licensed; MailKit/MimeKit and Microsoft.Data.Sqlite retain their own supplied notices. License alignment does not alter the protected projects.'),
('Design rule','All windows, controls, layout parameters, styles, templates, clock artwork placement and transforms are declared in XAML. Code handles data, events and domain behavior. The source reuses the approved sidebar, cards, grouped music list, schedule editor and player composition. It avoids an additional framework or ORM.')]),
('Project build and deployment',[
('Toolchain','The production target is net10.0-windows. A project-local .NET 10 LTS SDK is available under tools\\dotnet. Build intermediates go to dcu through Directory.Build.props, before SDK imports. The machine-wide .NET 9 SDK is not upgraded or replaced. Normal portable execution requires no administrator privileges.'),
('Build commands','Use tools\\build.ps1 for Debug or Release and optional win-x86 or win-x64 publishing. The script sets project-local DOTNET_CLI_HOME and NUGET_PACKAGES. Package versions are pinned in CarillonBells.csproj and packages.lock.json. Restore requires NuGet access. Self-contained publish includes the matching Windows runtime and SQLite native architecture.'),
('Artifacts','bin contains ordinary build outputs. export contains separate x86 and x64 evaluation ZIPs and release manifests. docs\\guides and docs\\pdf contain editable guides and PDF companions. samples\\empty-schema.sql creates a sanitized blank database. help contains local HTML and translation assets. images and icons holds extracted artwork and the executable icon.'),
('Portable base','AppContext.BaseDirectory is the sole application root. Runtime database is databases\\carillon.db; log is logs\\CarillonPlayLog.txt. Relative song and directory paths resolve from the executable directory, never Environment.CurrentDirectory. Packages include a relative launcher. The application can be extracted to another folder or drive without recompilation.'),
('Package truth','Self-contained means the end user need not install .NET separately. The package contains multiple runtime and native files; this build does not claim literal static single-EXE linking. Debug and Release builds are separate from the protected Delphi binaries. Source backup publication is separate from approval to replace production downloads.')]),
('Persistence and migration',[
('Repository','CarillonRepository uses Microsoft.Data.Sqlite directly, parameterized statements, short connections and explicit transactions. Playlist identity is the composite playlist_name and song_name key. Schedule records carry Song keys rather than grid positions. Table editing preserves original keys and commits changed rows.'),
('Serialization','DataFormats distinguishes missing times from midnight and accepts compatible date/time representations, including numeric OLE Automation values and historical text. User-facing dates use U.S. MM/dd/yyyy with slashes. Database writes retain yyyy-MM-dd and times retain HH:mm:ss. Durations are intervals: m:ss means minutes and seconds; h:mm:ss permits totals beyond twenty-four hours.'),
('Settings ownership','SystemFields and EmailFields identify permitted settings domains. SaveSettings updates only selected owned fields against settings_id=1. Administration computes changed fields from original row versions. This supports System-save then Email-save then System-save without stale unrelated values overwriting each other.'),
('Compatibility path','EnsureCompatibleSchema inspects columns before migration. It retains existing tables and constraints, adds compatible missing fields, ensures the stable settings key and creates weekly silence defaults if needed. Wide directory rotation is renamed to a preserved backup table, with a timestamp suffix when a prior backup exists, then copied into seven slot rows. Failure rolls back the migration.'),
('Backups and dispatch ledger','BackupZip uses the SQLite backup API to create a consistent temporary snapshot, compresses it and deletes only its own temporary file. Snapshot connections disable pooling so native handles are released before cleanup. Carillon9_Dispatched records occurrence identifiers and dates, supporting at-most-once dispatch across re-enable and restart. It is additional application-owned data; unknown legacy tables are retained.'),
('Import','The import screen opens the selected source in read-only mode, snapshots into a local temporary candidate, validates and upgrades that candidate, and backs up the current local database before replacement. Errors after replacement restore the prior ZIP snapshot. The source and verified baseline are never migration targets.')]),
('Scheduling calendar and silence',[
('Deterministic schedule builder','ScheduleBuilder filters inclusive From/Until dates and Monday-first weekday flags. Each distinct non-null time field creates an occurrence. Midnight is valid. Sorting uses time followed by stable playlist and path ordering. Weekly silence exclusions use inclusive end semantics during compilation. Full-day report builds are independent of the dispatch queue.'),
('Runtime ownership','CarillonRuntime owns one dispatcher timer, playback, endpoint state, settings, queue, logging and maintenance for the application lifetime. A supplied current-time function makes runtime clock behavior testable. Essential work continues when administration pages and the clock are closed or hidden. Tick guards prevent re-entry; playback completion is event driven.'),
('Clock discontinuities','The approved policy skips missed events after detected sleep/resume or wall-clock changes and prevents duplicate scheduled plays. Monotonic elapsed time is compared with wall-clock movement; gaps over ten seconds or drift over two seconds rebuild the queue. A date change rebuilds at midnight so the new day is represented, while daily maintenance remains after 00:05. Ambiguous fall-back clock times use one occurrence per local date and composite song key.'),
('Calendar','CalendarRules uses Gregorian Easter, source holiday dates and next-occurrence calculations. Christmas remains December 22 through 26, Memorial Day is the last Monday of May and Thanksgiving is the fourth Thursday in November. Group synchronization excludes Daily List, matches trimmed names case-insensitively, writes dates and time1 and clears times2 through12.'),
('Silence coordination','SilenceRule associates overnight windows with the starting weekday and treats equal start/end as inactive. Live windows exclude the exact end; compilation retains the source inclusive-end behavior. Runtime combines all weekly and legacy reasons, applies them immediately after startup/edits and preserves prior manual mute. Legacy date windows are calculated as intervals rather than blindly toggling mute at a timer instant, so restarting during a window remains safe.')]),
('Audio and Windows lifetime',[
('Independent decoding','AudioPlayback.OpenFile explicitly constructs Mp3FileReaderBase with NLayer.NAudioSupport.Mp3FrameDecompressor. Both MP3 duration reading and actual playback use this path. PCM, IEEE-float and extensible WAV use WaveFileReader. Unsupported compressed WAV fails visibly. Windows waveOut receives decoded PCM through NAudio; WPF MediaPlayer, DirectShow and Media Foundation are not used.'),
('Playback serialization','Play stops/releases a prior stream before opening another. Repeat count is clamped to 1 through5. PlaybackStopped marshals back to the WPF dispatcher, checks output ownership, seeks to zero for remaining repeats and raises completion when finished. Stop detaches the handler before stopping/disposal to prevent stale callbacks from reviving playback.'),
('Endpoint integration','SystemAudio uses MMDeviceEnumerator and AudioEndpointVolume. It subscribes to volume notifications and marshals callbacks asynchronously. A periodic default-device check rebinds when the default endpoint changes. Manual mute preference is tracked independently of managed silence. Shutdown unsubscribes before disposal and restores prior manual mute if managed silence was active.'),
('Power and locks','Application startup holds an exclusive executable-relative Carillon.lock and a database-adjacent lock. Locks are OS file handles and are released on exit or process termination. SetThreadExecutionState requests ES_CONTINUOUS and ES_SYSTEM_REQUIRED during application operation and releases the request at exit. A thirty-second keepalive writes into the portable data directory.'),
('Cleanup','The main window close path resolves pending edits, closes the clock, disconnects view subscriptions and disposes runtime resources. Runtime stops the timer, cancels background mail, releases audio streams and endpoint subscriptions and drops the power hold. App.OnExit releases database and instance handles. File Exit and X share this path.')]),
('UI reports logs and background jobs',[
('Playlist editing','The main window edits a clone of the selected Song. A fingerprint detects pending changes. Save and Cancel restore the prior schedule state. Automatic reloads replace the complete collection snapshot, preserve selection by composite key, reapply search, and restore group expansion and scroll offset after layout. Save uses the edited key when a group changes. No manual playlist Refresh button is provided.'),
('Administration','AdministrationWindow declares all domains in static XAML and keeps editable DataTables until explicit Save. It validates dates, complete one-off silence intervals, enabled weekly windows and annual directory date pairs. It saves only owned settings fields. Group and directory calculations use the repository and domain classes rather than generated FMX binding code.'),
('Clock and themes','ClockWindow uses the embedded original face in a 1680 by864 coordinate space with pivot 840,430. XAML polygons and RotateTransforms implement minute angle 6 times minute and hour angle 30 times hour plus0.5 times minute. Themes.xaml holds palette parameters; ThemeManager updates shared resources and persists compatible VCL background/text colors.'),
('Reporting','EmailReports builds escaped HTML using independent full-day schedule snapshots, recorded logs and actual runtime/backend/device state. It reports boot time, uptime, drives, CPU deltas, physical memory, playlist duration, missing files, prior-day errors and a health score. MailKit uses explicit STARTTLS and asynchronous authentication/send. Success is logged only after the transport succeeds.'),
('Logs and jobs','CarillonLog synchronizes append/read/trim, parses ISO and historical en-US timestamps, counts actual Played Song messages and ignores checkpoints. Trim keeps malformed lines and replaces the file through a temporary sibling. Startup and daily trimming, 00:05 schedule/count work, January liturgical/group maintenance, morning reporting, silence evaluation and keepalive all belong to runtime, not page visibility.')]),
('Validation and operating limits',[
('Automated checks','Run CarillonBells.exe --self-test for deterministic domain, repository, migration and logging tests. Results are written beside the executable. Tests create and remove isolated temporary databases. Run --audio-test followed by an MP3 path to exercise repeated MP3/WAV load/decode/duration, pause/resume/stop, repeats, scheduled playback with the clock visible and reopening the clock. The selected MP3 is read-only.'),
('Acceptance evidence','The acceptance matrix records exact executed checks and remaining environmental tests. Build success is not proof of hardware compatibility, long-running reliability, SMTP delivery or every DPI setting. Record those outcomes independently. Never send live SMTP messages merely to complete an automated test. Evaluation mode suppresses automatic delivery but does not suppress actual scheduled audio.'),
('Known environment-dependent checks','Real SMTP delivery requires an authorized recipient and configuration. USB drive-letter relocation, physical disconnect, audio device removal, multiple real monitor DPI settings and extended soak operation require suitable hardware or user evaluation. A testable clock allows deterministic discontinuity tests without changing Windows time.'),
('Publishing','Review staged files for private databases, logs, credentials, music, test artifacts and generated caches before commit. Use the account no-reply address locally without changing global identity. Publish only to the separate Carillon9 repository. Preserve 8.1 source, website and release assets. Package manifests identify tested source and SHA-256 hashes.'),
('Maintenance','Keep package versions pinned and update them deliberately with build, domain, database and audio tests. Preserve notices and native architecture matching. Edit XAML in the IDE for presentation changes. Avoid introducing runtime-only controls, generic helper frameworks or background services. Keep the source inventory, handoff decisions and acceptance matrix current as verified behavior changes.')])]

def make(title,sections,filename):
    doc=Document();sec=doc.sections[0];sec.top_margin=Inches(.75);sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.8)
    for border in doc.styles.element.xpath('.//w:pBdr'):
        border.getparent().remove(border)
    for name in ('Normal','Title','Subtitle','Heading 1','Heading 2','TOC 1'):
        if name not in doc.styles: continue
        style=doc.styles[name];style.font.name='Calibri';style.font.color.rgb=RGBColor(0,0,0)
    doc.styles['Normal'].font.size=Pt(10.5);doc.styles['Normal'].paragraph_format.space_after=Pt(8)
    doc.styles['Heading 1'].font.size=Pt(20);doc.styles['Heading 2'].font.size=Pt(11)
    doc.styles['Heading 2'].paragraph_format.space_before=Pt(9);doc.styles['Heading 2'].paragraph_format.space_after=Pt(3)
    doc.add_paragraph('Westminster Chimes and Carillon Bells',style='Title');doc.add_paragraph(title,style='Subtitle');doc.add_paragraph('Version 9.0\nSeparate C Sharp WPF edition\nLast changed '+DATE)
    doc.add_paragraph('This guide describes the separate C# application and its portable operation. Keep the live Delphi 8.1 installation intact while evaluating the replacement. Read the validation record before production use.')
    doc.add_page_break();doc.add_paragraph('Contents',style='TOC Heading')
    first=doc.add_paragraph();r=first.add_run();b=OxmlElement('w:fldChar');b.set(qn('w:fldCharType'),'begin');r._r.append(b);ins=OxmlElement('w:instrText');ins.set(qn('xml:space'),'preserve');ins.text=' TOC \\o "1-1" \\h \\z \\u ';r._r.append(ins);s=OxmlElement('w:fldChar');s.set(qn('w:fldCharType'),'separate');r._r.append(s)
    for i,(heading,_) in enumerate(sections):
        p=doc.add_paragraph();link=OxmlElement('w:hyperlink');link.set(qn('w:anchor'),f'chapter{i}');run=OxmlElement('w:r');t=OxmlElement('w:t');t.text=f'{heading}    {i+3}';run.append(t);link.append(run);p._p.append(link)
    end=OxmlElement('w:fldChar');end.set(qn('w:fldCharType'),'end');doc.paragraphs[-1].add_run()._r.append(end)
    doc.add_paragraph('This is a changeable table of contents field. After editing, use LibreOffice Tools then Update then Update All to refresh it.')
    for i,(heading,paragraphs) in enumerate(sections):
        doc.add_page_break();p=doc.add_paragraph(heading,style='Heading 1');start=OxmlElement('w:bookmarkStart');start.set(qn('w:id'),str(i+1));start.set(qn('w:name'),f'chapter{i}');p._p.insert(0,start);end=OxmlElement('w:bookmarkEnd');end.set(qn('w:id'),str(i+1));p._p.append(end)
        for sub,body in paragraphs: doc.add_paragraph(sub,style='Heading 2');doc.add_paragraph(body)
    footer=sec.footer.paragraphs[0];footer.alignment=2;footer.add_run('Carillon Bells 9.0   |   ');field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');footer._p.append(field)
    update=OxmlElement('w:updateFields');update.set(qn('w:val'),'true');doc.settings.element.append(update)
    doc.core_properties.title='Carillon Bells 9.0 '+title;doc.core_properties.author='Tommy Martin';doc.save(ROOT/'docs/guides'/filename)

if __name__=='__main__':
    make('User Guide',USER,'CarillonBells_9_0_User_Guide.docx')
    make('Engineering Guide',ENGINEER,'CarillonBells_9_0_Engineering_Guide.docx')
    print('Created editable guides with title pages, last-changed dates and TOC fields.')
